using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private const string DomainNs = "PaymentAuthorization.Domain";
    private const string ApplicationNs = "PaymentAuthorization.Application";
    private const string InfrastructureNs = "PaymentAuthorization.Infrastructure";

    // Technical details that belong in Infrastructure only.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Text.Json",
        "System.Diagnostics.Process", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
        "Newtonsoft.Json", "System.Threading.Tasks.Dataflow",
    ];

    private static readonly Assembly Domain = typeof(Money).Assembly;
    private static readonly Assembly Application = typeof(AuthorizePayment).Assembly;

    [Fact]
    public void Domain_does_not_depend_on_outer_layers()
        => AssertNoViolations(Types.InAssembly(Domain).ShouldNot()
            .HaveDependencyOnAny(ApplicationNs, InfrastructureNs).GetResult());

    [Fact]
    public void Application_does_not_depend_on_Infrastructure()
        => AssertNoViolations(Types.InAssembly(Application).ShouldNot()
            .HaveDependencyOn(InfrastructureNs).GetResult());

    [Fact]
    public void Domain_does_not_use_technical_details()
        => AssertNoViolations(Types.InAssembly(Domain).ShouldNot()
            .HaveDependencyOnAny(TechnicalNamespaces).GetResult());

    [Fact]
    public void Application_does_not_use_technical_details()
        => AssertNoViolations(Types.InAssembly(Application).ShouldNot()
            .HaveDependencyOnAny(TechnicalNamespaces).GetResult());

    [Fact]
    public void Layers_are_resolved_to_the_expected_assemblies()
    {
        Assert.Equal(DomainNs, Domain.GetName().Name);
        Assert.Equal(ApplicationNs, Application.GetName().Name);
        Assert.Equal(InfrastructureNs, typeof(FileSystemReceiptStore).Assembly.GetName().Name);
    }

    private static void AssertNoViolations(TestResult result)
        => Assert.True(result.IsSuccessful,
            "Layer violations: " + string.Join(", ", result.FailingTypeNames ?? []));
}
E
